//! Unit tests on near-sdk's mocked blockchain. Quote signatures are real ed25519 signatures,
//! checked by the mocked `ed25519_verify` host function.

use super::*;
use ed25519_dalek::{Signer, SigningKey};
use near_sdk::base64::engine::general_purpose::STANDARD as BASE64;
use near_sdk::base64::Engine;
use near_sdk::mock::MockAction;
use near_sdk::serde_json::{self, json, Value};
use near_sdk::test_utils::{get_created_receipts, get_logs, VMContextBuilder};
use near_sdk::{test_vm_config, testing_env, PromiseResult, RuntimeFeesConfig};

/// Generated by tests/fixtures/make_quote.mjs (TEST-ONLY keys).
const FIXTURE: &str = include_str!("../tests/fixtures/quote.json");
const NOW_MS: u64 = 1_800_000_000_000;
const AMOUNT: u128 = 2_850_000;

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).unwrap()
}

fn account(id: &str) -> AccountId {
    id.parse().unwrap()
}

fn owner() -> AccountId {
    account("owner.testnet")
}
fn operator() -> AccountId {
    account("relayer.testnet")
}
fn treasury() -> AccountId {
    account("treasury.testnet")
}
fn stranger() -> AccountId {
    account("mallory.testnet")
}
fn settlement_id() -> AccountId {
    account(fixture()["settlement"].as_str().unwrap())
}
fn token() -> AccountId {
    account(fixture()["token"].as_str().unwrap())
}
fn payer() -> AccountId {
    account(fixture()["payer"]["account_id"].as_str().unwrap())
}

fn hex32(hex: &str) -> [u8; 32] {
    let bytes: Vec<u8> =
        (0..hex.len()).step_by(2).map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap()).collect();
    bytes.try_into().unwrap()
}

fn signer_seed() -> [u8; 32] {
    hex32(fixture()["quote_signer"]["seed_hex"].as_str().unwrap())
}

fn signer_pk() -> String {
    fixture()["quote_signer"]["public_key"].as_str().unwrap().to_owned()
}

fn ed25519_pk(seed: &[u8; 32]) -> String {
    let key = SigningKey::from_bytes(seed).verifying_key().to_bytes();
    format!("ed25519:{}", near_sdk::bs58::encode(key).into_string())
}

fn context(predecessor: AccountId, now_ms: u64) -> VMContextBuilder {
    let mut builder = VMContextBuilder::new();
    builder
        .current_account_id(settlement_id())
        .signer_account_id(predecessor.clone())
        .predecessor_account_id(predecessor)
        .block_timestamp(now_ms * 1_000_000)
        .block_height(42);
    builder
}

fn call_as(predecessor: AccountId) {
    testing_env!(context(predecessor, NOW_MS).build());
}

fn call_as_at(predecessor: AccountId, now_ms: u64) {
    testing_env!(context(predecessor, now_ms).build());
}

/// The contract's own callback, with the result of the `ft_transfer` it follows.
fn callback_with(result: PromiseResult) {
    testing_env!(
        context(settlement_id(), NOW_MS).build(),
        test_vm_config(),
        RuntimeFeesConfig::test(),
        Default::default(),
        vec![result],
    );
}

fn setup() -> Settlement {
    call_as(owner());
    Settlement::new(owner(), operator(), treasury(), token(), signer_pk())
}

fn id(n: u64) -> String {
    format!("0x{n:064x}")
}

fn quote(n: u64) -> Value {
    json!({
        "quote_id": id(n),
        "payer": payer(),
        "token": token(),
        "token_amount": AMOUNT.to_string(),
        "fiat_currency": "THB",
        "fiat_amount": "10000",
        "merchant_ref_hash": format!("0x{}", "11".repeat(32)),
        "expires_at_ms": NOW_MS + 60_000,
    })
}

/// The backend's signing rule: ed25519 over the exact bytes of the quote JSON string.
fn sign_msg(quote: &Value, seed: &[u8; 32]) -> String {
    let quote_json = quote.to_string();
    let signature = SigningKey::from_bytes(seed).sign(quote_json.as_bytes()).to_bytes();
    json!({ "quote": quote_json, "signature": BASE64.encode(signature) }).to_string()
}

fn assert_kept_all(result: PromiseOrValue<U128>) {
    match result {
        PromiseOrValue::Value(U128(0)) => {}
        PromiseOrValue::Value(U128(n)) => panic!("returned {n} unused tokens"),
        PromiseOrValue::Promise(_) => panic!("returned a promise"),
    }
}

/// Pays `quote` as the token contract, signed by the configured quote key.
fn pay(contract: &mut Settlement, quote: &Value) {
    call_as(token());
    let amount = quote["token_amount"].as_str().unwrap().parse().unwrap();
    assert_kept_all(contract.ft_on_transfer(payer(), U128(amount), sign_msg(quote, &signer_seed())));
}

fn status(contract: &Settlement, quote_id: &str) -> String {
    contract.get_payment(quote_id.to_owned()).unwrap().status
}

fn events() -> Vec<Value> {
    get_logs()
        .iter()
        .filter_map(|log| log.strip_prefix("EVENT_JSON:"))
        .map(|json| serde_json::from_str(json).unwrap())
        .collect()
}

/// (receiver, method, args, deposit in yocto) of each function call the contract created.
fn calls() -> Vec<(String, String, Value, u128)> {
    get_created_receipts()
        .into_iter()
        .flat_map(|receipt| {
            let receiver = receipt.receiver_id.to_string();
            receipt.actions.into_iter().filter_map(move |action| match action {
                MockAction::FunctionCallWeight { method_name, args, attached_deposit, .. } => Some((
                    receiver.clone(),
                    String::from_utf8(method_name).unwrap(),
                    serde_json::from_slice(&args).unwrap(),
                    attached_deposit.as_yoctonear(),
                )),
                _ => None,
            })
        })
        .collect()
}

// ----------------------------------------------------------------------- fixture

#[test]
fn fixture_matches_the_rust_signer() {
    let f = fixture();
    let quote_json = f["quote_json"].as_str().unwrap();
    let signature = SigningKey::from_bytes(&signer_seed()).sign(quote_json.as_bytes()).to_bytes();
    assert_eq!(BASE64.encode(signature), f["signature_base64"].as_str().unwrap());
    assert_eq!(ed25519_pk(&signer_seed()), signer_pk());
    assert_eq!(serde_json::from_str::<Value>(quote_json).unwrap(), f["quote"]);
    let msg: Value = serde_json::from_str(f["msg"].as_str().unwrap()).unwrap();
    assert_eq!(msg, json!({ "quote": quote_json, "signature": f["signature_base64"] }));
}

#[test]
fn new_stores_the_config() {
    let contract = setup();
    assert_eq!(
        contract.get_config(),
        ConfigView {
            owner: owner(),
            operator: operator(),
            treasury: treasury(),
            token: token(),
            quote_signer_pk: signer_pk(),
        }
    );
    assert_eq!(contract.paid_count(), 0);
}

#[test]
#[should_panic(expected = "invalid public key")]
fn new_refuses_a_bad_quote_signer_key() {
    call_as(owner());
    Settlement::new(owner(), operator(), treasury(), token(), "secp256k1:abc".to_owned());
}

// ---------------------------------------------------------------------- payments

#[test]
fn good_payment_from_the_fixture() {
    let mut contract = setup();
    let f = fixture();
    call_as(token());
    let result = contract.ft_on_transfer(payer(), U128(AMOUNT), f["msg"].as_str().unwrap().to_owned());
    assert_kept_all(result);

    let quote_id = f["quote"]["quote_id"].as_str().unwrap();
    let expected = PaymentView {
        quote_id: quote_id.to_owned(),
        payer: payer(),
        token: token(),
        token_amount: U128(AMOUNT),
        fiat_currency: "THB".to_owned(),
        fiat_amount: U128(10_000),
        merchant_ref_hash: f["quote"]["merchant_ref_hash"].as_str().unwrap().to_owned(),
        status: "Paid".to_owned(),
        paid_block: 42,
        index: 0,
    };
    assert_eq!(contract.get_payment(quote_id.to_owned()), Some(expected));
    assert_eq!(contract.paid_count(), 1);
    assert_eq!(
        events(),
        vec![json!({
            "standard": "globalpay",
            "version": "1.0.0",
            "event": "payment_received",
            "data": [{
                "quote_id": quote_id,
                "payer": payer(),
                "token": token(),
                "token_amount": "2850000",
                "fiat_currency": "THB",
                "fiat_amount": "10000",
                "merchant_ref_hash": f["quote"]["merchant_ref_hash"],
                "status": "Paid",
                "paid_block": 42,
                "index": 0,
            }],
        })]
    );
    // The view takes the id in any case.
    assert!(contract.get_payment(quote_id.to_uppercase().replace("0X", "0x")).is_some());
    assert_eq!(contract.get_payment(id(7)), None);
    assert_eq!(contract.get_payment("not an id".to_owned()), None);
}

