#[test]
fn paid_log_keeps_the_order_and_pages() {
    let mut contract = setup();
    for n in [3, 1, 2] {
        pay(&mut contract, &quote(n));
    }
    assert_eq!(contract.paid_count(), 3);

    let page = |from, limit| -> Vec<(String, u64)> {
        contract.get_paid_events(from, limit).into_iter().map(|p| (p.quote_id, p.index)).collect()
    };
    assert_eq!(page(0, 10), vec![(id(3), 0), (id(1), 1), (id(2), 2)]);
    assert_eq!(page(0, 2), vec![(id(3), 0), (id(1), 1)]);
    assert_eq!(page(2, 2), vec![(id(2), 2)]);
    assert_eq!(page(1, u64::MAX), vec![(id(1), 1), (id(2), 2)]);
    assert_eq!(page(3, 1), vec![]);
    assert_eq!(page(100, 5), vec![]);
    assert_eq!(page(0, 0), vec![]);

    // Events show the current status.
    call_as(operator());
    let _ = contract.settle(id(1));
    assert_eq!(contract.get_paid_events(1, 1)[0].status, "Settled");
}

// ------------------------------------------------------------- settle and refund

#[test]
fn settle_sends_the_tokens_to_the_treasury() {
    let mut contract = setup();
    pay(&mut contract, &quote(1));
    call_as(operator());
    let _ = contract.settle(id(1));
    assert_eq!(status(&contract, &id(1)), "Settled");

    let calls = calls();
    assert_eq!(calls.len(), 2);
    assert_eq!(calls[0].0, token().to_string());
    assert_eq!(calls[0].1, "ft_transfer");
    assert_eq!(calls[0].2["receiver_id"], json!(treasury()));
    assert_eq!(calls[0].2["amount"], json!("2850000"));
    assert_eq!(calls[0].3, 1, "ft_transfer needs exactly 1 yoctoNEAR");
    assert_eq!(calls[1].0, settlement_id().to_string());
    assert_eq!(calls[1].1, "on_payout");
    assert_eq!(calls[1].2, json!({ "quote_id": id(1), "payout": "Settle" }));
    assert_eq!(calls[1].3, 0);

    callback_with(PromiseResult::Successful(vec![]));
    assert!(contract.on_payout(id(1), Payout::Settle));
    assert_eq!(status(&contract, &id(1)), "Settled");
    assert_eq!(
        events(),
        vec![json!({
            "standard": "globalpay",
            "version": "1.0.0",
            "event": "settled",
            "data": [{
                "quote_id": id(1),
                "action": "settle",
                "token": token(),
                "receiver_id": treasury(),
                "token_amount": "2850000",
            }],
        })]
    );
}

#[test]
fn refund_sends_the_tokens_back_to_the_payer() {
    let mut contract = setup();
    pay(&mut contract, &quote(1));
    call_as(operator());
    let _ = contract.refund(id(1));
    assert_eq!(status(&contract, &id(1)), "Refunded");
    let calls = calls();
    assert_eq!(calls[0].1, "ft_transfer");
    assert_eq!(calls[0].2["receiver_id"], json!(payer()));
    assert_eq!(calls[0].3, 1);
    assert_eq!(calls[1].2, json!({ "quote_id": id(1), "payout": "Refund" }));

    callback_with(PromiseResult::Successful(vec![]));
    assert!(contract.on_payout(id(1), Payout::Refund));
    assert_eq!(status(&contract, &id(1)), "Refunded");
    let events = events();
    assert_eq!(events[0]["event"], "refunded");
    assert_eq!(events[0]["data"][0]["receiver_id"], json!(payer()));
}

#[test]
fn failed_transfer_rolls_back_to_paid() {
    let mut contract = setup();
    pay(&mut contract, &quote(1));
    call_as(operator());
    let _ = contract.settle(id(1));
    assert_eq!(status(&contract, &id(1)), "Settled");

    callback_with(PromiseResult::Failed);
    assert!(!contract.on_payout(id(1), Payout::Settle));
    assert_eq!(status(&contract, &id(1)), "Paid");
    let events = events();
    assert_eq!(events.len(), 1);
    assert_eq!(events[0]["event"], "payout_failed");
    assert_eq!(events[0]["data"][0]["action"], "settle");

    // Back to Paid, so the operator can try again (here: refund instead).
    call_as(operator());
    let _ = contract.refund(id(1));
    assert_eq!(status(&contract, &id(1)), "Refunded");
    callback_with(PromiseResult::Failed);
    assert!(!contract.on_payout(id(1), Payout::Refund));
    assert_eq!(status(&contract, &id(1)), "Paid");
}

