#[test]
fn owner_can_change_the_operator() {
    let mut contract = setup();
    pay(&mut contract, &quote(1));
    call_as(owner());
    contract.set_operator(account("ops2.testnet"));
    assert_eq!(contract.get_config().operator, account("ops2.testnet"));
    call_as(account("ops2.testnet"));
    let _ = contract.settle(id(1));
    assert_eq!(status(&contract, &id(1)), "Settled");
}

